import { pudding, type InteractionContext, type JSONValue } from '@pudding/widget';
import { z } from 'zod';
import { analyze, createGame, describe, levels, paint, playable, rotate, RuleError, trace, undo, validateLayout, type Brush, type Direction, type Game, type Level, type Task } from './rules';
import { errorText, t } from './text';

const cellSchema = z.string().regex(/^[A-F][1-6]$/);
export const levelSchema = z.object({
  id: z.string().min(1).max(64), title: z.string().max(60),
  source: z.object({cell: cellSchema, direction: z.enum(['right','down','left','up'])}).strict(),
  target: cellSchema,
  mirrors: z.array(z.object({cell: cellSchema, tilt: z.enum(['/','\\'])}).strict()).max(8),
  walls: z.array(cellSchema).max(34),
}).strict();
export function current(): Game { return pudding.state.read().data.game as unknown as Game || createGame(levels[0]); }
let changing = false;
async function exclusive<T>(fn: () => Promise<T>) {
  if (changing) throw new RuleError('busy');
  changing = true;
  try { return await fn(); } finally { changing = false; }
}
function cancelled(context?: InteractionContext) { if (context?.signal.aborted) throw new RuleError('cancelled'); }
function participant(context: InteractionContext) {
  const run = pudding.interaction.read();
  return context.actor?.runID === run?.id ? run?.participants.find(p => p.id === context.actor?.participantID) : undefined;
}
function requireHuman(context: InteractionContext) {
  cancelled(context);
  if (context.sessionID || context.actor && participant(context)?.kind !== 'human') throw new RuleError('humanOnly');
}
function requireAssistant(context: InteractionContext, tasks: Task[]) {
  cancelled(context);
  const game = current(), run = pudding.interaction.read();
  if (!game.assistant || !run || run.status !== 'running' || context.actor?.runID !== run.id ||
      game.assistant.runID !== run.id || game.assistant.participantID !== context.actor?.participantID ||
      !participant(context) || !tasks.includes(game.assistant.task)) throw new RuleError('noAssignment');
  return game.assistant;
}
async function write(game: Game, version: number, context?: InteractionContext) {
  cancelled(context);
  return pudding.state.write({ expectedVersion: version, data: { game: game as unknown as JSONValue } });
}
export function readBoard() { return { ...describe(current()), stateVersion: pudding.state.read().version }; }
export async function humanChange(change: (game: Game) => Game, context: InteractionContext) {
  return exclusive(async () => {
    requireHuman(context);
    const snapshot = pudding.state.read(), old = current();
    const next = { ...change(old), assistant: null };
    await write(next, snapshot.version, context);
    if (pudding.interaction.read()) await pudding.interaction.setRequests([]);
    return readBoard();
  });
}
export const humanRotate = (cell: string, context: InteractionContext) =>
  context.sessionID || context.actor && participant(context)?.kind !== 'human'
    ? assistantRotate({cell}, context)
    : humanChange(game => rotate(game, cell), context);
export const humanUndo = (context: InteractionContext) => humanChange(undo, context);
export const reset = (context: InteractionContext) => humanChange(game => createGame(game.level, game.sound), context);
export const loadLevel = (level: Level, context: InteractionContext) => humanChange(game => {
  playable(level); return createGame(level, game.sound);
}, context);
export const startEditor = (fresh: boolean, context: InteractionContext) => humanChange(game => ({
  ...game, mode: 'edit', hint: null,
  draft: fresh ? { id: crypto.randomUUID(), title: '', source: {cell:'A4',direction:'right'}, target:'F2', mirrors:[], walls:[] }
    : { ...game.level, id: crypto.randomUUID(), title: game.level.title, mirrors: game.mirrors.map(m => ({...m})) },
}), context);
export const paintCell = (cell: string, brush: Brush, direction: Direction, context: InteractionContext) => humanChange(game => {
  if (!game.draft || game.mode !== 'edit') throw new RuleError('editing');
  return { ...game, draft: paint(game.draft, cell, brush, direction), hint: null };
}, context);
export const cancelEditor = (context: InteractionContext) => humanChange(game => ({ ...game, mode: 'play', draft: null }), context);
export const launchDraft = (context: InteractionContext, title?: string) => humanChange(game => {
  if (!game.draft) throw new RuleError('editing');
  const level = {...game.draft,title:title === undefined ? game.draft.title : title.trim().slice(0,60)};
  playable(level); return createGame(level, game.sound);
}, context);

export async function saveLevel(context: InteractionContext, title?: string) {
  return exclusive(async () => {
    requireHuman(context);
    const game = current(), original = game.mode === 'edit' ? game.draft! : game.level;
    const level = {...original,title:title === undefined ? original.title : title.trim().slice(0,60)};
    playable(level);
    const saved = await pudding.storage.read({signal: context.signal});
    const library = saved.data.levels as unknown as Level[] || [];
    const next = library.filter(l => l.id !== level.id);
    if (next.length >= 30) throw new RuleError('libraryFull');
    cancelled(context);
    await pudding.storage.write({expectedVersion: saved.version, data: {...saved.data, levels: [...next, level] as unknown as JSONValue}});
  });
}
export async function deleteLevel(id: string, context: InteractionContext) {
  requireHuman(context);
  const saved = await pudding.storage.read({signal: context.signal});
  const library = saved.data.levels as unknown as Level[] || [];
  cancelled(context);
  await pudding.storage.write({expectedVersion: saved.version, data: {...saved.data, levels: library.filter(l => l.id !== id) as unknown as JSONValue}});
}

async function publish() {
  const game = current(), assignment = game.assistant, run = pudding.interaction.read();
  if (!assignment || !run || run.status !== 'running') {
    if (run) await pudding.interaction.setRequests([]);
    return;
  }
  const id = assignment.id + ':' + pudding.state.read().version;
  await pudding.interaction.notify({
    id, audience: {kind:'selected', participantIDs:[assignment.participantID]}, delivery:'request-action', topic:'light-workshop',
    summary: t(assignment.task), message: t('requestMessage', {task:t(assignment.task)}) + '\n' + assignment.brief,
    data: readBoard() as unknown as JSONValue,
  });
  await pudding.interaction.setRequests([{notificationID:id, participantID:assignment.participantID}]);
}
export async function requestAssistant(sessionID: string, task: Task, brief: string, context: InteractionContext) {
  return exclusive(async () => {
    requireHuman(context);
    if (!sessionID) throw new RuleError('chooseAgent');
    if (task !== 'design' && (current().mode !== 'play' || trace(current().level, current().mirrors).outcome === 'solved')) throw new RuleError('finished');
    // Invalidate the old assignment before connecting or resuming a participant.
    let version = pudding.state.read().version;
    await write({...current(), assistant:null}, version, context);
    if (pudding.interaction.read()) await pudding.interaction.setRequests([]);
    let run = await pudding.interaction.connect({sessionIDs:[sessionID]});
    if (run.status === 'paused') run = await pudding.interaction.resume();
    const who = run.participants.find(p => p.kind !== 'human');
    if (!who) throw new RuleError('chooseAgent');
    version = pudding.state.read().version;
    const game = current();
    await write({...game, assistant:{id:crypto.randomUUID(),participantID:who.id,runID:run.id,task,steps:0,brief:brief.trim().slice(0,400)}, hint:null}, version, context);
    await publish();
  });
}
export const stopAssistant = (context: InteractionContext) => humanChange(game => ({...game,hint:null}), context);

async function assistantRotate(input: {cell:string;comment?:string}, context: InteractionContext) {
  return exclusive(async () => {
    const assignment = requireAssistant(context,['step','solve']);
    const version = pudding.state.read().version;
    let next = rotate(current(), input.cell);
    const done = assignment.task === 'step' || trace(next.level,next.mirrors).outcome === 'solved' || assignment.steps + 1 >= 32;
    next = {...next, assistant:done ? null : {...assignment,steps:assignment.steps+1},hint:input.comment ? {text:input.comment,cell:input.cell} : null};
    await write(next,version,context);
    // A delivered move remains successful even if scheduling the next turn fails.
    try { await publish(); } catch (error) { return {ok:true,...readBoard(),notificationError:errorText(error)}; }
    return {ok:true,...readBoard()};
  });
}
async function showHint(input: {text:string;cell?:string}, context: InteractionContext) {
  return exclusive(async () => {
    const assignment = requireAssistant(context,['hint','point']);
    if (input.cell && !current().mirrors.some(m => m.cell === input.cell)) throw new RuleError('notMirror');
    if (assignment.task === 'hint' && input.cell) throw new RuleError('hintOnly');
    if (assignment.task === 'point' && !input.cell) throw new RuleError('notMirror');
    const version = pudding.state.read().version;
    await write({...current(),assistant:null,hint:{text:input.text,cell:input.cell || null}},version,context);
    try { await publish(); } catch (error) { return {ok:true,...readBoard(),notificationError:errorText(error)}; }
    return {ok:true,...readBoard()};
  });
}
async function submitLevel(level: Level, context: InteractionContext) {
  return exclusive(async () => {
    requireAssistant(context,['design']);
    const check = playable(level), version = pudding.state.read().version;
    const next = createGame({...level,id:crypto.randomUUID()},current().sound);
    await write(next,version,context);
    try { await publish(); } catch (error) { return {ok:true,...readBoard(),validation:check,notificationError:errorText(error)}; }
    return {ok:true,...readBoard(),validation:check};
  });
}
export function registerInterfaces() {
  function define<T>(definition: Parameters<typeof pudding.defineInterface<T>>[0]) {
    return pudding.defineInterface({...definition, async run(input,context) {
      try { return await definition.run(input,context); }
      catch (error) {
        if (!(error instanceof RuleError)) throw error;
        return {ok:false,executed:false,code:error.code,message:errorText(error),...readBoard()};
      }
    }});
  }
  return [
    define({name:'readBoard',description:t('readDescription'),input:z.object({}).strict(),run:readBoard}),
    define({name:'rotateMirror',description:t('rotateDescription'),input:z.object({cell:cellSchema,comment:z.string().max(160).optional()}).strict(),run:assistantRotate}),
    define({name:'showHint',description:t('hintDescription'),input:z.object({text:z.string().trim().min(1).max(400),cell:cellSchema.optional()}).strict(),run:showHint}),
    define({name:'validatePuzzle',description:t('validateDescription'),input:z.object({level:levelSchema}).strict(),run:({level},context) => {
      requireAssistant(context,['design']); validateLayout(level); return analyze(level);
    }}),
    define({name:'submitPuzzle',description:t('submitDescription'),input:z.object({level:levelSchema}).strict(),run:({level},context) => submitLevel(level,context)}),
    pudding.interaction.onResume(async () => { if (!changing && current().assistant) await publish(); }),
  ];
}

